class Table:
    __slots__ = ("name", "entries")

    def __init__(self, name, entries):
        self.name = name
        self.entries = entries

    def __getitem__(self, key):
        for entry in self.entries:
            if entry[0] == key or entry[0] == 4294967295:
                return entry[1]

        raise KeyError(f"Key {key} not found in table {self.name}.")

