def transform_control_codes(instr):
    instr.req_bit_set = 0
    for bit in instr.bar:
        instr.req_bit_set |= 1 << bit

    instr.src_rel_sb = instr.rb
    instr.dst_wr_sb = instr.wb

    yb = 0 if instr.yb else 1
    instr.usched_info = instr.stall | (yb << 4)


